/* Shared code following partproc; generated by tools/overlay_src.py, stubs replaced by C as functions are matched. Starts at 0x00273A80 (was partproc_00273A80.c). */
#include "common.h"
#include "include_asm.h"

typedef int u128 __attribute__((mode(TI)));
extern unsigned char *batalia_span_particle_textures_ptr;
extern unsigned char *create_part(int);
extern float random_float_between(float, float);
extern void vec_scale_to_length(void *, void *, float);
extern int truncate_float_to_s32_r(float) __asm__("func_001FA898");
extern void FastVecAdd(void *, void *, void *);

// Spawns a particle at a position with a color and scale chosen by kind.
void spawn_span_particle(float *pos, int kind, float *vec, float scale) {
    float v[4];
    float *vp = v;
    float w[4];
    float u[4];
    unsigned char *p;
    int k2 = kind;
    int c;
    float s;
    float f20;
    int k;
    *(u128 *)v = *(u128 *)vec;
    p = create_part(0);
    if (p != 0) {
        c = 0;
        k = k2;
        f20 = 0.0f;
        s = f20;
        switch (k) {
        case 0:
            c = 0x14;
            f20 = 0.015f;
            s = random_float_between(0.01f, 1.0f);
            break;
        case 1:
            c = 0xD;
            f20 = 0.5f;
            s = random_float_between(1.0f, 5.0f);
            break;
        case 2:
            c = 0xD;
            f20 = 1.0f;
            k = 1;
            s = random_float_between(20.0f, 30.0f);
            break;
        }
        *(u128 *)w = *(u128 *)vp;
        vec_scale_to_length(w, w, s);
        *(short *)(p + 0xA) = k2;
        *(int *)(p + 4) = ((c >> 2) << 24) | 0x606060;
        *(int *)(p + 0xC) = (c << 24) | 0x907070;
        p[9] = truncate_float_to_s32_r(4.0f) + 0x60;
        p[3] = 0x44;
        p[1] = 3;
        p[2] = batalia_span_particle_textures_ptr[k];
        *(u128 *)(p + 0x10) = *(u128 *)pos;
        FastVecAdd(u, pos, w);
        *(u128 *)(p + 0x20) = *(u128 *)u;
        *(float *)(p + 0x1C) = f20;
        *(float *)(p + 0x2C) = 1.0f;
        *(u128 *)(p + 0x30) = *(u128 *)vp;
        *(float *)(p + 0x3C) = scale;
    }
}
